class Solution {
  public String complexNumberMultiply(String num1, String num2) {
    int split1 = num1.indexOf('+'), split2 = num2.indexOf('+');
    int a = Integer.parseInt(num1.substring(0, split1));
    int b = Integer.parseInt(num1.substring(split1 + 1, num1.length() - 1));
    int c = Integer.parseInt(num2.substring(0, split2));
    int d = Integer.parseInt(num2.substring(split2 + 1, num2.length() - 1));
    return (a * c - b * d) + "+" + (a * d + b * c) + "i";
  }
}
